// CRISPY_REPORT_BASIC_SIGNATURE:financial-statements-parity-v7
// Financial Statements strict template for Crispy report payload.

#set text(font: "Inter 18pt", size: 9pt)

// ---------- Helpers ----------
#let asText(value) = if value == none { "" } else { str(value) }

#let getFiltersMap() = if "filters_map" in data { data.at("filters_map") } else { () }

#let getFilterValue(filterKey, fallback: "") = {
  let filtersMap = getFiltersMap()
  if filterKey in filtersMap { asText(filtersMap.at(filterKey)) } else { fallback }
}

#let hasFilterValue(filterKey) = getFilterValue(filterKey) != ""

#let getRowIndent(row) = if ("indent" in row) and row.at("indent") != none { row.at("indent") } else { 0 }

#let rowIsImportant(row) = {
  let hasParentAccount = ("parent_account" in row) and asText(row.at("parent_account")) != ""
  let hasParentSection = ("parent_section" in row) and asText(row.at("parent_section")) != ""
  let isTotal = ("is_total_row" in row) and row.at("is_total_row")
  isTotal or not (hasParentAccount or hasParentSection)
}

#let rowWeight(row) = if rowIsImportant(row) { "bold" } else { "regular" }

#let rowIsBlank(row) = {
  if not ("cells" in row) or row.cells.len() == 0 { true } else { asText(row.cells.at(0).value) == "" }
}

#let rowInset(row) = if rowIsBlank(row) {
  (top: 12pt, right: 2pt, bottom: 12pt, left: 2pt)
} else {
  (top: 2pt, right: 2pt, bottom: 2pt, left: 2pt)
}

#let columnWidth(col) = if ("width" in col) and col.width != "auto" { eval(col.width) } else { auto }

#let summaryValueFill(item) = {
  if ("color_class" in item) and item.color_class == "green" {
    rgb("#22C55E")
  } else if ("color_class" in item) and item.color_class == "red" {
    rgb("#EF4444")
  } else if ("color_class" in item) and item.color_class == "blue" {
    rgb("#3B82F6")
  } else {
    rgb("#0f172a")
  }
}

#let summaryValueText(item) = {
  if ("formatted_value" in item) and item.formatted_value != "" {
    asText(item.formatted_value)
  } else {
    asText(item.value)
  }
}

#let summarySeparatorText(item) = {
  let raw = asText(item.value)
  if raw == "-" {
    "−"
  } else {
    raw
  }
}

#let summaryIsProfitLossLayout() = {
  let hasFiveItems = data.report_summary.len() == 5
  let secondIsSeparator = ("type" in data.report_summary.at(1)) and data.report_summary.at(1).type == "separator"
  let fourthIsSeparator = ("type" in data.report_summary.at(3)) and data.report_summary.at(3).type == "separator"
  hasFiveItems and secondIsSeparator and fourthIsSeparator
}

#let resolvedCurrency() = {
  if hasFilterValue("presentation_currency") {
    getFilterValue("presentation_currency")
  } else if hasFilterValue("currency") {
    getFilterValue("currency")
  } else if ("report_summary" in data) {
    let currencyItems = data.report_summary.filter(item => ("currency" in item) and asText(item.currency) != "")
    if currencyItems.len() > 0 {
      asText(currencyItems.at(0).currency)
    } else {
      ""
    }
  } else {
    ""
  }
}

#let cellFill(row, cell) = {
  if rowIsImportant(row) and ("warn_if_negative" in row) and row.warn_if_negative and cell.is_numeric and cell.raw_value != none and cell.raw_value < 0 {
    rgb("#EF4444")
  } else {
    rgb("#0f172a")
  }
}

// ---------- Header ----------
#align(center)[
  #text(size: 16pt, weight: "bold")[#data.title]

  #if hasFilterValue("company") [
    #v(0.2em)
    #text(size: 13pt)[#getFilterValue("company")]
  ]

  #if hasFilterValue("cost_center") [
    #v(0.2em)
    #text(size: 12pt)[#getFilterValue("cost_center")]
  ]

  #if hasFilterValue("fiscal_year") [
    #v(0.2em)
    #text(size: 12pt)[#getFilterValue("fiscal_year")]
  ]

  #let currencyText = resolvedCurrency()
  #if currencyText != "" [
    #v(0.2em)
    #text(size: 10pt, fill: rgb("#666"))[Currency: #currencyText]
  ]

  #if hasFilterValue("from_date") and hasFilterValue("to_date") [
    #v(0.2em)
    #text(size: 10pt, fill: rgb("#666"))[
      #getFilterValue("from_date") - #getFilterValue("to_date")
    ]
  ]
]

#v(0.6em)
#line(length: 100%, stroke: (paint: rgb("#ddd"), thickness: 0.5pt))
#v(0.6em)

#if ("subtitle" in data) and data.subtitle != "" [
  #text(size: 9pt, fill: rgb("#666"))[#data.subtitle]
  #v(0.4em)
  #line(length: 100%, stroke: (paint: rgb("#eee"), thickness: 0.5pt))
  #v(0.6em)
]

// ---------- Summary ----------
#if ("report_summary" in data) and data.report_summary.len() > 0 [
  #block(
    inset: (x: 8pt, y: 8pt),
    width: 100%,
    stroke: (paint: rgb("#e5e7eb"), thickness: 0.5pt),
    radius: 3pt,
  )[
    #if summaryIsProfitLossLayout() [
      #let summary0 = data.report_summary.at(0)
      #let summary1 = data.report_summary.at(1)
      #let summary2 = data.report_summary.at(2)
      #let summary3 = data.report_summary.at(3)
      #let summary4 = data.report_summary.at(4)

      #grid(
        columns: (1fr, 1fr, 1fr, 1fr, 1fr),
        column-gutter: 14pt,
        row-gutter: 6pt,

        text(size: 7.5pt, fill: rgb("#666"))[#asText(summary0.label)],
        text(size: 7.5pt, fill: rgb("#666"))[],
        text(size: 7.5pt, fill: rgb("#666"))[#asText(summary2.label)],
        text(size: 7.5pt, fill: rgb("#666"))[],
        text(size: 7.5pt, fill: rgb("#666"))[#asText(summary4.label)],

        text(size: 10.5pt, weight: "bold", fill: summaryValueFill(summary0))[#summaryValueText(summary0)],
        align(center + horizon)[
          #text(size: 11pt, weight: "semibold", fill: summaryValueFill(summary1))[#summarySeparatorText(summary1)]
        ],
        text(size: 10.5pt, weight: "bold", fill: summaryValueFill(summary2))[#summaryValueText(summary2)],
        align(center + horizon)[
          #text(size: 11pt, weight: "semibold", fill: summaryValueFill(summary3))[#summarySeparatorText(summary3)]
        ],
        text(size: 10.5pt, weight: "bold", fill: summaryValueFill(summary4))[#summaryValueText(summary4)],
      )
    ] else [
      #grid(
        columns: data.report_summary.map(item => if ("type" in item) and item.type == "separator" { auto } else { 1fr }),
        column-gutter: 10pt,
        row-gutter: 6pt,
        ..data.report_summary.map(item => {
          if ("type" in item) and item.type == "separator" {
            block(width: 100%)[
              #text(size: 7pt, fill: rgb("#666"))[ ]
              #v(0.15em)
              #align(center + horizon)[
                #text(size: 11pt, weight: "semibold", fill: summaryValueFill(item))[#summarySeparatorText(item)]
              ]
            ]
          } else {
            block(width: 100%)[
              #text(size: 7pt, fill: rgb("#666"))[#asText(item.label)]
              #v(0.15em)
              #text(size: 9.5pt, weight: "bold", fill: summaryValueFill(item))[#summaryValueText(item)]
            ]
          }
        })
      )
    ]
  ]
  #v(0.8em)
]

// ---------- Guard ----------
#if data.columns.len() > 8 [
  #block(fill: rgb("#fff4f4"), inset: 10pt, stroke: (paint: rgb("#f1aaaa"), thickness: 0.5pt), radius: 3pt)[
    #text(weight: "bold", fill: rgb("#a94442"))[
      Too many columns. Export the report and print it using a spreadsheet application.
    ]
  ]
] else [
  // ---------- Table ----------
  #table(
    columns: data.columns.map(columnWidth),

    stroke: (x, y) => (
      top: if y == 0 { 0.5pt } else { 0.5pt },
      bottom: 0.5pt,
      left: 0pt,
      right: 0pt,
    ),

    align: (x, y) => if x == 0 { left + horizon } else { right + horizon },

    fill: (x, y) => if y == 0 { rgb("f8fafc") } else { none },

    inset: (top: 2pt, right: 2pt, bottom: 2pt, left: 2pt),

    table.header(
      ..data.columns.map(col => text(weight: "semibold")[#asText(col.label)])
    ),

    ..data.rows.map(row => {
      row.cells.enumerate().map(cellEntry => {
        let idx = cellEntry.at(0)
        let cell = cellEntry.at(1)

        let base = text(weight: rowWeight(row), fill: cellFill(row, cell))[#asText(cell.value)]

        if idx == 0 {
          box(inset: (left: getRowIndent(row) * 2em) + rowInset(row))[#base]
        } else {
          box(inset: rowInset(row))[#base]
        }
      })
    }).flatten()
  )
]

#v(0.8em)
#align(right)[
  #text(size: 8pt, fill: rgb("#666"))[Total Records: #data.total_rows]
]

// CRISPY_REPORT_BASIC_SIGNATURE:bank-reconciliation-statement-parity-v13
// Bank Reconciliation Statement parity-focused template with:
// 1. stronger balance/summary rows
// 2. bold reference labels
// 3. accounting-style currency alignment

#set text(font: "Inter 18pt", size: 9pt)

#let asText(value) = if value == none { "" } else { str(value) }

#let rowText(row, key) = if key in row { asText(row.at(key)) } else { "" }

#let hasPostingDate(row) = rowText(row, "posting_date") != ""
#let hasPaymentEntry(row) = rowText(row, "payment_entry") != ""
#let isSummaryRow(row) = not hasPostingDate(row) and hasPaymentEntry(row)
#let isSpacerRow(row) = not hasPostingDate(row) and not hasPaymentEntry(row) and rowText(row, "debit") == "" and rowText(row, "credit") == ""

#let referenceBlock(row) = {
  let againstAccount = rowText(row, "against_account")
  let referenceNo = rowText(row, "reference_no")
  let referenceDate = rowText(row, "ref_date")
  let clearanceDate = rowText(row, "clearance_date")

  if againstAccount == "" and referenceNo == "" and referenceDate == "" and clearanceDate == "" {
    []
  } else [
    #if againstAccount != "" [
      #text(size: 8.5pt)[#strong[Against:] #againstAccount]
    ]
    #if referenceNo != "" [
      #if againstAccount != "" [#linebreak()]
      #text(size: 8.5pt)[#strong[Reference:] #referenceNo]
    ]
    #if referenceDate != "" [
      #if againstAccount != "" or referenceNo != "" [#linebreak()]
      #text(size: 8.5pt)[#strong[Reference Date:] #referenceDate]
    ]
    #if clearanceDate != "" [
      #if againstAccount != "" or referenceNo != "" or referenceDate != "" [#linebreak()]
      #text(size: 8.5pt)[#strong[Clearance Date:] #clearanceDate]
    ]
  ]
}

#let postingDateCell(row) = if hasPostingDate(row) {
  [#rowText(row, "posting_date")]
} else {
  []
}

#let paymentEntryCell(row) = if hasPostingDate(row) {
  [#rowText(row, "payment_entry")]
} else {
  []
}

#let referenceCell(row) = if hasPostingDate(row) {
  referenceBlock(row)
} else if isSummaryRow(row) {
  [#text(weight: "bold")[#rowText(row, "payment_entry")]]
} else {
  []
}

#let accountingAmountCell(row, amountKey) = {
  let currencyText = rowText(row, amountKey + "_currency_display")
  let amountText = rowText(row, amountKey + "_amount_display")
  let fallbackText = rowText(row, amountKey)
  let resolvedAmount = if amountText != "" { amountText } else { fallbackText }

  if resolvedAmount == "" {
    []
  } else if isSummaryRow(row) [
    #text(weight: "bold")[
      #if currencyText != "" [
        #box(width: 100%)[#currencyText #h(1fr) #resolvedAmount]
      ] else [
        #box(width: 100%)[#h(1fr) #resolvedAmount]
      ]
    ]
  ] else [
    #if currencyText != "" [
      #box(width: 100%)[#currencyText #h(1fr) #resolvedAmount]
    ] else [
      #box(width: 100%)[#h(1fr) #resolvedAmount]
    ]
  ]
}

#let accountText = if "filters_map" in data and "account" in data.filters_map {
  asText(data.filters_map.at("account"))
} else {
  ""
}

#let reportDateText = if "filters_map" in data and "report_date" in data.filters_map {
  asText(data.filters_map.at("report_date"))
} else {
  ""
}

#let companyText = if "filters_map" in data and "company" in data.filters_map {
  asText(data.filters_map.at("company"))
} else {
  ""
}

#align(center)[
  #text(size: 16pt, weight: "bold")[#data.title]

  #if accountText != "" or reportDateText != "" or companyText != "" [
    #v(0.25em)
    #text(size: 10pt, fill: rgb("#666"))[
      #if accountText != "" [#accountText]
      #if accountText != "" and reportDateText != "" [, ]
      #if reportDateText != "" [#reportDateText]
      #if companyText != "" [
        #if accountText != "" or reportDateText != "" [ ]
        #companyText
      ]
    ]
  ]
]

#v(0.6em)
#line(length: 100%, stroke: (paint: rgb("#ddd"), thickness: 0.5pt))
#v(0.8em)

#table(
  columns: (2.2fr, 3fr, 6.8fr, 2.6fr, 2.6fr),

  stroke: (x, y) => (
    top: 0.5pt,
    bottom: 0.5pt,
    left: 0.5pt,
    right: 0.5pt,
  ),

  fill: (x, y) => {
    if y == 0 {
      rgb("#f8fafc")
    } else if y - 1 < data.rows.len() and isSummaryRow(data.rows.at(y - 1)) {
      rgb("#f4f7fb")
    } else {
      none
    }
  },

  align: left + horizon,

  inset: (top: 6pt, right: 6pt, bottom: 6pt, left: 6pt),

  table.header(
    text(weight: "semibold")[Posting Date],
    text(weight: "semibold")[Payment Entry],
    text(weight: "semibold")[Reference],
    align(right + horizon)[#text(weight: "semibold")[Debit]],
    align(right + horizon)[#text(weight: "semibold")[Credit]],
  ),

  ..data.rows.map(row => (
    postingDateCell(row),
    paymentEntryCell(row),
    referenceCell(row),
    accountingAmountCell(row, "debit"),
    accountingAmountCell(row, "credit"),
  )).flatten(),
)

#if data.show_totals [
  #v(0.8em)
  #align(right)[
    #text(size: 8pt, fill: rgb("#666"))[Total Records: #data.total_rows]
  ]
]

// CRISPY_REPORT_BASIC_SIGNATURE:general-ledger-parity-v4
// General Ledger parity-focused template for crispy-print report mode.

#set text(font: "Inter 18pt", size: 9pt)

#let rawText(value) = if value == none { "" } else { str(value) }

#let cleanText(value) = {
  let text = rawText(value)
  if text == "[]" or text == "()" or text == "{}" or text == "none" {
    ""
  } else {
    text
  }
}

#let rowText(row, key) = if key in row { cleanText(row.at(key)) } else { "" }

#let filterText(key) = if "filters_map" in data and key in data.filters_map {
  cleanText(data.filters_map.at(key))
} else {
  ""
}

#let showTotals = if "show_totals" in data { data.show_totals } else { true }

#let accountOrPartyText = if filterText("party_name") != "" {
  filterText("party_name")
} else if filterText("party") != "" {
  filterText("party")
} else {
  filterText("account")
}

#let taxIdText = filterText("tax_id")
#let fromDateText = filterText("from_date")
#let toDateText = filterText("to_date")

#let hasPostingDate(row) = rowText(row, "posting_date") != ""
#let summaryLabel(row) = rowText(row, "account")
#let isSummaryRow(row) = not hasPostingDate(row) and summaryLabel(row) != ""
#let isOpeningLike(row) = isSummaryRow(row) and summaryLabel(row).contains("Opening")
#let isClosingLike(row) = isSummaryRow(row) and summaryLabel(row).contains("Closing")
#let isTotalLike(row) = isSummaryRow(row) and summaryLabel(row).contains("Total")
#let isNamedGroupRow(row) = isSummaryRow(row) and not isOpeningLike(row) and not isClosingLike(row) and not isTotalLike(row)

#let isNegativeAmount(text) = text != "" and text.starts-with("-")

#let currencyAmountCell(row, field) = {
  let currencyText = rowText(row, field + "_currency_display")
  let amountText = rowText(row, field + "_amount_display")
  let fallbackText = rowText(row, field)
  let resolvedAmount = if amountText != "" { amountText } else { fallbackText }
  let amountFill = if field == "balance" and isNegativeAmount(resolvedAmount) { rgb("#c92a2a") } else { rgb("#111827") }

  if resolvedAmount == "" {
    []
  } else if currencyText != "" [
    #box(width: 100%)[
      #text(fill: amountFill)[#currencyText] #h(1fr) #text(fill: amountFill)[#resolvedAmount]
    ]
  ] else [
    #box(width: 100%)[
      #h(1fr) #text(fill: amountFill)[#resolvedAmount]
    ]
  ]
}

#let referenceCell(row) = if hasPostingDate(row) {
  [
    #if rowText(row, "voucher_type") != "" [#rowText(row, "voucher_type")]
    #if rowText(row, "voucher_type") != "" and rowText(row, "voucher_no") != "" [#linebreak()]
    #if rowText(row, "voucher_no") != "" [#rowText(row, "voucher_no")]
  ]
} else {
  []
}

#let primaryRemarksLine(row) = {
  let showPartyLine = filterText("party") == "" and filterText("account") == ""

  if showPartyLine and rowText(row, "party_name") != "" {
    rowText(row, "party_name")
  } else if showPartyLine and rowText(row, "party") != "" {
    rowText(row, "party")
  } else if showPartyLine and rowText(row, "account") != "" {
    rowText(row, "account")
  } else {
    ""
  }
}

#let detailRemarksLine(row) = if rowText(row, "remarks") != "" {
  ("Remarks", rowText(row, "remarks"))
} else if rowText(row, "bill_no") != "" {
  ("Supplier Invoice No", rowText(row, "bill_no"))
} else {
  none
}

#let remarksCell(row) = if hasPostingDate(row) {
  [
    #let primaryLine = primaryRemarksLine(row)
    #let detailLine = detailRemarksLine(row)

    #if primaryLine != "" [
      #text(size: 8.5pt, fill: rgb("#6b7280"))[#primaryLine]
    ]

    #if detailLine != none [
      #if primaryLine != "" [#linebreak()]
      #strong[#detailLine.at(0):] #detailLine.at(1)
    ]
  ]
